/*
 * Panel de lista de exclusión de INV-07.
 * Sin un solo color literal: todo sale de las variables --bw-* de tokens.css.
 */

.panel {
  display: flex;
  flex-direction: column;
  gap: 20px;
}

/* Modo «Visible para todos» o miembro sin permiso: las etiquetas siguen viéndose. */
.panel[data-active='false'] {
  opacity: 0.5;
  filter: grayscale(0.3);
}

.section {
  display: flex;
  flex-direction: column;
}

.sectionTitle {
  margin: 0 0 10px;
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--bw-ink-steel);
}

/* ── Buscador de organizaciones ────────────────────────────────────────── */

.input {
  width: 100%;
  padding: 9px 12px;
  border: 1px solid var(--bw-line-steel-strong);
  border-radius: 6px;
  background: var(--bw-surface-mist);
  font-family: var(--bw-font-body);
  font-size: var(--bw-size-input);
  color: var(--bw-input-text);
  outline: none;
  transition: border-color 0.15s;
}

.input::placeholder {
  color: var(--bw-input-placeholder);
}

.input:focus:not(:disabled) {
  border-color: var(--bw-calibration-blue);
  box-shadow: var(--bw-focus-halo);
}

.input:disabled {
  cursor: not-allowed;
}

.candidates {
  display: flex;
  flex-direction: column;
  gap: 4px;
  margin: 10px 0 0;
  padding: 0;
  list-style: none;
}

.candidate {
  width: 100%;
  padding: 8px 10px;
  border: 1px solid var(--bw-line-steel);
  border-radius: var(--bw-radius);
  background: var(--bw-surface-mist);
  font-family: var(--bw-font-body);
  font-size: 13px;
  color: var(--bw-deep-steel);
  text-align: left;
  cursor: pointer;
  transition: border-color 0.12s, background 0.12s;
}

.candidate:hover {
  border-color: var(--bw-hover-border);
  background: var(--bw-hover-surface);
}

/* ── Geografía ─────────────────────────────────────────────────────────── */

.geoRow {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-end;
  gap: 8px;
}

.field {
  display: flex;
  flex: 1;
  min-width: 180px;
  flex-direction: column;
  gap: 4px;
}

.fieldLabel {
  font-size: var(--bw-size-label);
  font-weight: 500;
  letter-spacing: var(--bw-ls-label);
  color: var(--bw-steel-mist);
}

.select {
  width: 100%;
  padding: 9px 12px;
  border: 1px solid var(--bw-line-steel-strong);
  border-radius: 6px;
  background: var(--bw-surface-mist);
  font-family: var(--bw-font-body);
  font-size: var(--bw-size-input);
  color: var(--bw-input-text);
  outline: none;
  cursor: pointer;
  transition: border-color 0.15s;
}

.select:focus:not(:disabled) {
  border-color: var(--bw-calibration-blue);
  box-shadow: var(--bw-focus-halo);
}

.select:disabled {
  cursor: not-allowed;
}

.addGeo {
  height: 36px;
  padding: 0 14px;
  flex-shrink: 0;
  border: none;
  border-radius: 6px;
  background: var(--bw-deep-steel);
  color: var(--bw-on-dark-hover);
  font-family: var(--bw-font-body);
  font-size: 13px;
  font-weight: 500;
  cursor: pointer;
  transition: opacity 0.12s;
}

.addGeo:hover:not(:disabled) {
  opacity: 0.85;
}

.addGeo:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}

/* ── Hints ─────────────────────────────────────────────────────────────── */

.hint {
  margin: 6px 0 0;
  font-family: var(--bw-font-mono);
  font-size: var(--bw-size-hint);
  letter-spacing: var(--bw-ls-hint);
  text-transform: uppercase;
  color: var(--bw-input-placeholder);
}

/* ── Etiquetas eliminables ─────────────────────────────────────────────── */

.tags {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin-top: 10px;
}

.tag {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 4px 10px;
  border: 1px solid var(--bw-chip-active-border);
  border-radius: 20px;
  background: var(--bw-chip-active-bg);
  font-size: 12px;
  font-weight: 500;
  color: var(--bw-deep-steel);
}

.tagGeo {
  border-color: var(--bw-tag-border);
  background: var(--bw-tag-bg);
}

.tagLabel {
  line-height: 1.4;
}

.tagRemove {
  display: flex;
  align-items: center;
  padding: 0;
  border: none;
  background: none;
  font-family: inherit;
  font-size: 14px;
  line-height: 1;
  color: var(--bw-steel-mist);
  cursor: pointer;
  transition: color 0.12s;
}

.tagRemove:hover:not(:disabled) {
  color: var(--bw-danger);
}

.tagRemove:disabled {
  color: var(--bw-hint-steel);
  cursor: not-allowed;
}

/* ── Error de una exclusión ────────────────────────────────────────────── */

.alert {
  margin: 0;
  padding: 10px 12px;
  border: 1px solid var(--bw-badge-danger-border);
  border-radius: 4px;
  background: var(--bw-sensitive-bg);
  font-size: 13px;
  color: var(--bw-error-text);
}

import type { Zone } from '../../lib/search';
import {
  CONTINENT_OPTIONS,
  type CountryOption,
  type Exclusion,
  type OrgCandidate,
} from '../../lib/visibility';
import styles from './ExclusionPanel.module.css';

interface Props {
  /** Exclusiones por organización (`kind === 'ORG'`), ya agrupadas y ordenadas. */
  orgs: Exclusion[];
  /** Exclusiones geográficas (continente y país juntos), ya agrupadas y ordenadas. */
  geo: Exclusion[];
  /** Los candidatos ya filtrados por `filterOrgCandidates`; el panel no filtra nada. */
  candidates: OrgCandidate[];
  query: string;
  continent: Zone | '';
  country: string;
  /** Los países del continente elegido; los pide la pantalla, no el panel. */
  countries: CountryOption[];
  /** Modo «Visible para todos» o miembro sin permiso de gestión. */
  disabled: boolean;
  busy: boolean;
  error: string | null;
  onQueryChange: (q: string) => void;
  onPickOrg: (c: OrgCandidate) => void;
  onContinentChange: (c: Zone | '') => void;
  onCountryChange: (code: string) => void;
  onAddGeo: () => void;
  onRemove: (e: Exclusion) => void;
}

/**
 * El panel de lista de exclusión de INV-07 (spec §3). Presentacional: no toca la
 * red, no tiene estado propio — `query`, `continent` y `country` llegan por props
 * y se devuelven por callback. Añadir o quitar es de efecto inmediato, así que
 * este panel no guarda nada por su cuenta.
 */
export function ExclusionPanel({
  orgs,
  geo,
  candidates,
  query,
  continent,
  country,
  countries,
  disabled,
  busy,
  error,
  onQueryChange,
  onPickOrg,
  onContinentChange,
  onCountryChange,
  onAddGeo,
  onRemove,
}: Props) {
  function renderTag(exclusion: Exclusion, isGeo: boolean) {
    return (
      <span
        key={exclusion.id}
        className={isGeo ? `${styles.tag} ${styles.tagGeo}` : styles.tag}
      >
        <span className={styles.tagLabel}>{exclusion.label}</span>
        <button
          type="button"
          className={styles.tagRemove}
          aria-label={'Quitar ' + exclusion.label}
          disabled={disabled || busy}
          onClick={() => onRemove(exclusion)}
        >
          ×
        </button>
      </span>
    );
  }

  return (
    <div
      className={styles.panel}
      data-testid="exclusion-panel"
      data-active={disabled ? 'false' : 'true'}
    >
      <section className={styles.section} aria-label="Exclusión por organización">
        <h3 className={styles.sectionTitle}>Exclusión por organización</h3>
        <input
          className={styles.input}
          type="text"
          placeholder="Buscar organización por nombre..."
          value={query}
          disabled={disabled}
          onChange={(e) => onQueryChange(e.target.value)}
        />
        <p className={styles.hint}>EFECTO INMEDIATO AL AÑADIR</p>

        {candidates.length > 0 && (
          <ul className={styles.candidates}>
            {candidates.map((c) => (
              <li key={c.id}>
                <button type="button" className={styles.candidate} onClick={() => onPickOrg(c)}>
                  {c.name}
                </button>
              </li>
            ))}
          </ul>
        )}

        <div className={styles.tags}>{orgs.map((e) => renderTag(e, false))}</div>
      </section>

      <section className={styles.section} aria-label="Exclusión por geografía">
        <h3 className={styles.sectionTitle}>Exclusión por geografía</h3>

        <div className={styles.geoRow}>
          <label className={styles.field}>
            <span className={styles.fieldLabel}>Excluir por continente</span>
            <select
              className={styles.select}
              value={continent}
              disabled={disabled}
              onChange={(e) => onContinentChange(e.target.value as Zone | '')}
            >
              <option value="">Selecciona un continente</option>
              {CONTINENT_OPTIONS.map((c) => (
                <option key={c.code} value={c.code}>
                  {c.label}
                </option>
              ))}
            </select>
          </label>

          {continent !== '' && (
            <label className={styles.field}>
              <span className={styles.fieldLabel}>Refinar por país</span>
              <select
                className={styles.select}
                value={country}
                disabled={disabled}
                onChange={(e) => onCountryChange(e.target.value)}
              >
                <option value="">Todos los países del continente</option>
                {countries.map((c) => (
                  <option key={c.code} value={c.code}>
                    {c.label}
                  </option>
                ))}
              </select>
            </label>
          )}

          <button
            type="button"
            className={styles.addGeo}
            disabled={disabled || busy || continent === ''}
            onClick={onAddGeo}
          >
            Añadir exclusión geográfica
          </button>
        </div>

        <p className={styles.hint}>
          EXCLUYE TODAS LAS ORGANIZACIONES CON SEDE EN ESA GEOGRAFÍA
        </p>

        <div className={styles.tags}>{geo.map((e) => renderTag(e, true))}</div>
      </section>

      {error !== null && (
        <p className={styles.alert} role="alert">
          {error}
        </p>
      )}
    </div>
  );
}

