/*
 * INV-07 — Visibilidad del inventario (Módulo 02).
 * Ningún color literal: todo sale de las variables --bw-* de tokens.css.
 */

/* La raíz es hija directa de `.bwcnt` (overflow: hidden): ella misma scrollea. */
.screen {
  display: flex;
  flex-direction: column;
  flex: 1;
  min-height: 0;
  overflow-y: auto;
}

.eyebrow {
  margin: 0 0 6px;
  font-family: var(--bw-font-title);
  font-size: var(--bw-size-hint);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--bw-steel-mist);
}

.title {
  margin: 0 0 4px;
  font-family: var(--bw-font-title);
  font-size: var(--bw-size-title);
  font-weight: 700;
  letter-spacing: var(--bw-ls-title);
  color: var(--bw-deep-steel);
}

.subtitle {
  margin: 0 0 28px;
  max-width: 600px;
  font-size: 14px;
  line-height: 1.6;
  color: var(--bw-steel-mist);
}

/* ── Avisos de la pantalla ─────────────────────────────────────────────── */

.status {
  margin: 14px 0 0;
  padding: 10px 14px;
  background: var(--bw-badge-success-bg);
  border: 1px solid var(--bw-badge-success-border);
  border-radius: 4px;
  font-size: 13px;
  color: var(--bw-success-dark);
}

.alert {
  margin: 0 0 16px;
  padding: 10px 14px;
  background: var(--bw-sensitive-bg);
  border: 1px solid var(--bw-badge-danger-border);
  border-radius: 4px;
  font-size: 13px;
  color: var(--bw-error-text);
}

.readOnly {
  margin: 0 0 20px;
  padding: 10px 14px;
  background: var(--bw-surface-mist);
  border: 1px solid var(--bw-line-steel);
  border-radius: 4px;
  font-size: 13px;
  color: var(--bw-steel-mist);
}

/* ── Contenedores ──────────────────────────────────────────────────────── */

.card,
.modeCard {
  /* El token más claro de la paleta hace de «papel» de tarjeta sobre el fondo frío. */
  background: var(--bw-warm-cream);
  border: 1px solid var(--bw-line-steel);
  border-radius: 8px;
  padding: 24px;
  margin: 0 0 20px;
}

.modeCard {
  min-inline-size: auto;
}

.cardTitle {
  display: block;
  padding: 0;
  margin: 0 0 16px;
  font-family: var(--bw-font-title);
  font-size: 13px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.07em;
  color: var(--bw-steel-mist);
}

/* ── Selector de modo ──────────────────────────────────────────────────── */

.radios {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.radio {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  padding: var(--bw-pad-radio);
  border: 1.5px solid var(--bw-line-steel);
  border-radius: 8px;
  cursor: pointer;
  transition: border-color 0.15s;
}

.radio:hover {
  border-color: var(--bw-calibration-blue);
}

.radioSelected {
  border-color: var(--bw-calibration-blue);
  background: var(--bw-chip-active-bg);
}

.radioInput {
  width: 16px;
  height: 16px;
  margin: 2px 0 0;
  flex-shrink: 0;
  accent-color: var(--bw-calibration-blue);
}

.radioText {
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.radioLabel {
  font-size: 14px;
  font-weight: 600;
  color: var(--bw-deep-steel);
}

.radioDescription {
  font-size: 13px;
  line-height: 1.5;
  color: var(--bw-steel-mist);
}

/* ── Bloque brass y aviso de lista conservada ──────────────────────────── */

.brassBlock {
  margin: 0 0 20px;
  padding: 12px 14px;
  background: var(--bw-tag-bg);
  border: 1px solid var(--bw-brass-border-strong);
  border-radius: 6px;
}

.brassText {
  margin: 0;
  font-size: 13px;
  line-height: 1.5;
  color: var(--bw-steel-mist);
}

.notice {
  margin: 12px 0 0;
  padding: 10px 14px;
  background: var(--bw-tag-bg);
  border: 1px solid var(--bw-brass-border);
  border-radius: 6px;
  font-size: 13px;
  line-height: 1.5;
  color: var(--bw-ink-steel);
}

/* ── Acción primaria ───────────────────────────────────────────────────── */

.actions {
  display: flex;
  margin: 0 0 4px;
}

.primary {
  height: 40px;
  padding: 0 22px;
  border: none;
  border-radius: 6px;
  background: var(--bw-calibration-blue);
  color: var(--bw-on-dark-hover);
  font-family: var(--bw-font-body);
  font-size: 14px;
  font-weight: 500;
  cursor: pointer;
  transition: background 0.12s;
}

.primary:hover:not(:disabled) {
  background: var(--bw-primary-dark);
}

.primary:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

