import { useEffect, useState } from 'react';
import type { Zone } from '../../lib/search';
import { errorMessage, type MemberProfile } from '../../lib/session';
import {
  addExclusion,
  canManageVisibility,
  DEFAULT_VISIBILITY_MODE,
  fetchContinentCountries,
  fetchOrgCandidates,
  fetchVisibility,
  filterOrgCandidates,
  groupExclusions,
  IMMEDIATE_EFFECT_NOTICE,
  KEPT_LIST_NOTICE,
  READ_ONLY_NOTICE,
  removeExclusion,
  SAVED_MESSAGE,
  saveVisibilityMode,
  VISIBILITY_MODES,
  type CountryOption,
  type Exclusion,
  type OrgCandidate,
  type VisibilityMode,
} from '../../lib/visibility';
import { ExclusionPanel } from './ExclusionPanel';
import styles from './Visibility.module.css';

const EYEBROW = 'Módulo 02 · Gestión de Inventario';
const TITLE = 'Visibilidad del inventario';
const SUBTITLE =
  'Controla quién puede ver tu stock en Bearingworld.io. El modo se aplica a todo tu inventario de forma inmediata.';

/**
 * INV-07 — Configuración de Visibilidad del Inventario.
 *
 * La pantalla posee TODO el estado: el modo guardado, el modo del radio (borrador
 * que no toca la red), la lista completa de exclusiones y el estado del buscador
 * de organizaciones. Las exclusiones se escriben al momento; el modo solo se
 * escribe al pulsar `Guardar configuración`.
 *
 * No lleva migración: `organizations.inventory_visibility_mode` e
 * `inventory_exclusions` existen desde `0002`.
 */
export function Visibility({ profile }: { profile: MemberProfile }) {
  /** Quién puede escribir lo decide la base (`exclusions_write_admin`); la UI solo lo refleja. */
  const canManage = canManageVisibility(profile.role);

  /** El modo que está GUARDADO en la organización. */
  const [savedMode, setSavedMode] = useState<VisibilityMode>(DEFAULT_VISIBILITY_MODE);
  /** El modo del radio: un borrador. Cambiarlo NO llama a la red. */
  const [draftMode, setDraftMode] = useState<VisibilityMode>(DEFAULT_VISIBILITY_MODE);
  const [exclusions, setExclusions] = useState<Exclusion[]>([]);

  /** El directorio completo, para que el filtrado de candidatos sea de cliente. */
  const [allOrgs, setAllOrgs] = useState<OrgCandidate[]>([]);

  /** Estado del buscador de organizaciones y de los dos selects de geografía. */
  const [query, setQuery] = useState('');
  const [continent, setContinent] = useState<Zone | ''>('');
  const [country, setCountry] = useState('');
  const [countries, setCountries] = useState<CountryOption[]>([]);

  const [loadError, setLoadError] = useState<string | null>(null);
  /** Error de una exclusión (añadir/quitar): va en la prop `error` del panel. */
  const [panelError, setPanelError] = useState<string | null>(null);
  const [saveError, setSaveError] = useState<string | null>(null);
  /** Aviso de éxito del guardado: un solo `role="status"` a la vez. */
  const [notice, setNotice] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);

  /** Carga UNA vez al montar: el modo guardado y la lista completa de exclusiones. */
  useEffect(() => {
    let active = true;

    fetchVisibility(profile.orgId)
      .then((state) => {
        if (!active) return;
        setSavedMode(state.mode);
        // El borrador arranca igual que lo guardado.
        setDraftMode(state.mode);
        setExclusions(state.exclusions);
      })
      .catch((e: unknown) => {
        if (!active) return;
        setLoadError(errorMessage(e));
      });

    fetchOrgCandidates()
      .then((next) => {
        if (!active) return;
        setAllOrgs(next);
      })
      .catch((e: unknown) => {
        if (!active) return;
        setLoadError(errorMessage(e));
      });

    return () => {
      active = false;
    };
  }, [profile.orgId]);

  /** Repide la lista después de una exclusión que ha ido bien. */
  async function reloadExclusions(): Promise<void> {
    const state = await fetchVisibility(profile.orgId);
    setExclusions(state.exclusions);
  }

  async function handlePickOrg(candidate: OrgCandidate): Promise<void> {
    setBusy(true);
    setPanelError(null);
    try {
      await addExclusion(profile.orgId, { orgId: candidate.id });
      await reloadExclusions();
      setQuery('');
    } catch (e: unknown) {
      // Sin recarga: solo el error dentro del panel.
      setPanelError(errorMessage(e));
    } finally {
      setBusy(false);
    }
  }

  function handleContinentChange(code: Zone | ''): void {
    setContinent(code);
    setCountry('');
    setPanelError(null);
    if (code === '') {
      setCountries([]);
      return;
    }
    fetchContinentCountries(code)
      .then((next) => setCountries(next))
      .catch((e: unknown) => setPanelError(errorMessage(e)));
  }

  async function handleAddGeo(): Promise<void> {
    if (continent === '') return;
    setBusy(true);
    setPanelError(null);
    try {
      if (country !== '') {
        await addExclusion(profile.orgId, { country });
      } else {
        await addExclusion(profile.orgId, { continent });
      }
      await reloadExclusions();
      setContinent('');
      setCountry('');
    } catch (e: unknown) {
      setPanelError(errorMessage(e));
    } finally {
      setBusy(false);
    }
  }

  async function handleRemove(exclusion: Exclusion): Promise<void> {
    setBusy(true);
    setPanelError(null);
    try {
      await removeExclusion(exclusion.id);
      await reloadExclusions();
    } catch (e: unknown) {
      setPanelError(errorMessage(e));
    } finally {
      setBusy(false);
    }
  }

  async function handleSave(): Promise<void> {
    setBusy(true);
    setSaveError(null);
    // Un solo aviso a la vez: si este guardado falla, no queda ningún status.
    setNotice(null);
    try {
      await saveVisibilityMode(profile.orgId, draftMode);
      setSavedMode(draftMode);
      setNotice(SAVED_MESSAGE);
    } catch (e: unknown) {
      setSaveError(errorMessage(e));
    } finally {
      setBusy(false);
    }
  }

  const candidates = filterOrgCandidates(allOrgs, query, exclusions, profile.orgId);
  const { orgs, geo } = groupExclusions(exclusions);

  /** El panel solo existe en modo restringido o cuando hay lista que enseñar. */
  const showPanel = draftMode === 'RESTRINGIDA' || exclusions.length > 0;
  const panelDisabled = draftMode === 'VISIBLE_TODOS' || !canManage;

  return (
    <div className={styles.screen} data-saved-mode={savedMode}>
      <p className={styles.eyebrow}>{EYEBROW}</p>
      <h1 className={styles.title}>{TITLE}</h1>
      <p className={styles.subtitle}>{SUBTITLE}</p>

      {!canManage && <p className={styles.readOnly}>{READ_ONLY_NOTICE}</p>}

      {loadError !== null && (
        <p className={styles.alert} role="alert">
          {loadError}
        </p>
      )}

      <fieldset className={styles.modeCard} role="radiogroup" aria-label="Modo de visibilidad">
        <legend className={styles.cardTitle}>Modo de visibilidad</legend>
        <div className={styles.radios}>
          {VISIBILITY_MODES.map((mode) => {
            const selected = draftMode === mode.value;
            return (
              <label
                key={mode.value}
                className={selected ? `${styles.radio} ${styles.radioSelected}` : styles.radio}
              >
                <input
                  className={styles.radioInput}
                  type="radio"
                  name="visibility-mode"
                  value={mode.value}
                  checked={selected}
                  disabled={!canManage}
                  aria-label={mode.label}
                  // Cambiar el radio SOLO mueve el borrador: ninguna llamada de red.
                  onChange={() => setDraftMode(mode.value)}
                />
                <span className={styles.radioText}>
                  <span className={styles.radioLabel}>{mode.label}</span>
                  <span className={styles.radioDescription}>{mode.description}</span>
                </span>
              </label>
            );
          })}
        </div>
      </fieldset>

      {/* Spec §6: se vuelve a «Visible para todos» con lista guardada. */}
      {draftMode === 'VISIBLE_TODOS' && exclusions.length > 0 && (
        <p className={styles.notice}>{KEPT_LIST_NOTICE}</p>
      )}

      {showPanel && (
        <div className={styles.card}>
          <p className={styles.cardTitle}>Lista de exclusión</p>
          <ExclusionPanel
            orgs={orgs}
            geo={geo}
            candidates={candidates}
            query={query}
            continent={continent}
            country={country}
            countries={countries}
            disabled={panelDisabled}
            busy={busy}
            error={panelError}
            onQueryChange={setQuery}
            onPickOrg={(c) => {
              void handlePickOrg(c);
            }}
            onContinentChange={handleContinentChange}
            onCountryChange={setCountry}
            onAddGeo={() => {
              void handleAddGeo();
            }}
            onRemove={(e) => {
              void handleRemove(e);
            }}
          />
        </div>
      )}

      <div className={styles.brassBlock}>
        <p className={styles.brassText}>{IMMEDIATE_EFFECT_NOTICE}</p>
      </div>

      <div className={styles.actions}>
        <button
          type="button"
          className={styles.primary}
          disabled={!canManage || busy}
          onClick={() => {
            void handleSave();
          }}
        >
          Guardar configuración
        </button>
      </div>

      {notice !== null && (
        <p className={styles.status} role="status">
          {notice}
        </p>
      )}

      {saveError !== null && (
        <p className={styles.alert} role="alert">
          {saveError}
        </p>
      )}
    </div>
  );
}
